def resolve(path, cwd, links):
    # Start with cwd if path is relative, otherwise start with /
    if path.startswith('/'):
        current = '/'
        components = [c for c in path.split('/') if c and c != '.']
    else:
        current = cwd
        components = [c for c in path.split('/') if c and c != '.']

    link_count = 0
    i = 0

    while i < len(components):
        component = components[i]

        if component == '..':
            # Move to parent directory
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
            i += 1
        else:
            # Append component to current path
            if current == '/':
                candidate = '/' + component
            else:
                candidate = current + '/' + component

            # Check if this path is a symlink
            if candidate in links:
                link_count += 1
                if link_count > 8:
                    return None

                # Get the link target
                target = links[candidate]

                # Parse the target
                if target.startswith('/'):
                    # Absolute symlink target
                    current = '/'
                    target_components = [c for c in target.split('/') if c and c != '.']
                else:
                    # Relative symlink target - relative to the directory containing the link
                    # current is the directory containing the link
                    target_components = [c for c in target.split('/') if c and c != '.']

                # Insert target components into the remaining components
                components = target_components + components[i+1:]
                i = 0
            else:
                # Not a symlink, just move to this path
                current = candidate
                i += 1

    # Return the result
    if current == '/':
        return '/'
    else:
        return current

